async function cut(b){life();bot.deactivateItem();if(['stone','granite','andesite','diorite','cobblestone','sandstone','coal_ore','deepslate','cobbled_deepslate','tuff','stone_bricks','cracked_stone_bricks','mossy_stone_bricks'].includes(b.name)){const p=bot.inventory.items().find(i=>i.name.endsWith('_pickaxe'));if(p)await bot.equip(p,'hand');else await bot.unequip('hand')}else await bot.unequip('hand');let timer;try{await Promise.race([bot.dig(b,true),new Promise((_,r)=>timer=setTimeout(()=>{bot.stopDigging();r(Error('CUT_BOUND'))},Math.min(8000,bot.digTime(b)+1800)))])}finally{clearTimeout(timer)}await tick(4);if(full(bot.blockAt(b.position)))throw Error('CUT_NO_ACK')}
function shell(p){if(!full(bot.blockAt(p.offset(0,-1,0)))||!full(bot.blockAt(p.offset(0,2,0))))return false;return dirs.every(d=>[0,1].every(y=>full(bot.blockAt(p.plus(d).offset(0,y,0)))))}
async function rescueCap(){const t=global.P1DownPending;if(!t||lost)return false;for(let k=0;k<35&&(!bot.entity.onGround||Math.abs(bot.entity.position.y-t.feet.y)>.12);k++)await tick(1);if(!t.feet.equals(bot.entity.position.floored())||!stock())return false;const roof=t.roof;if(!full(bot.blockAt(roof))){await bot.equip(stock(),'hand');const rd=dirs.find(d=>full(bot.blockAt(roof.plus(d))));if(!rd)throw Error('RESCUE_NO_ANCHOR');await bot._placeBlockWithOptions(bot.blockAt(roof.plus(rd)),rd.scaled(-1),{forceLook:true});await tick(5)}if(!shell(t.feet))return false;global.P1Overland=t;global.P1DownPending=null;console.log('RESCUE_CAP_VERIFIED',t.feet,bot.health);return true}
async function refuge(){bot.pathfinder.setGoal(null);bot.clearControlStates();if(bot.entity.isInWater)throw Error('REFUGE_WET');const candidates=bot.findBlocks({matching:b=>(bot.inventory.items().some(i=>i.name.endsWith('_pickaxe'))?['grass_block','dirt','stone','granite','diorite','andesite','sandstone','sand']:['grass_block','dirt']).includes(b.name),maxDistance:12,count:250});const q=candidates.find(q=>{if(q.y>bot.entity.position.y+.1||bot.entity.position.y-q.y>5||!air(bot.blockAt(q.offset(0,1,0)))||!air(bot.blockAt(q.offset(0,2,0))))return false;for(let y=-3;y<=0;y++)if(!full(bot.blockAt(q.offset(0,y,0))))return false;for(let y=-2;y<=0;y++)if(!dirs.every(d=>full(bot.blockAt(q.plus(d).offset(0,y,0)))))return false;return true});if(!q)throw Error('NO_REFUGE_SITE');if(!await moveTo(q.x+.5,q.z+.5,8000,.1,q.y+1))throw Error('REFUGE_APPROACH');await center(q);const snow=bot.blockAt(q.offset(0,1,0));if(snow.name==='snow')await cut(snow);global.P1DownPending={feet:q.offset(0,-2,0),roof:q,at:Date.now()};for(let y=0;y>=-2;y--){await cut(bot.blockAt(q.offset(0,y,0)));for(let k=0;k<35&&(!bot.entity.onGround||Math.abs(bot.entity.position.y-(q.y+y))>.12);k++)await tick(1);if(!bot.entity.onGround||Math.abs(bot.entity.position.y-(q.y+y))>.12)throw Error('REFUGE_SETTLE '+bot.entity.position)}if(!stock())throw Error('NO_CAP');await bot.equip(stock(),'hand');await bot._placeBlockWithOptions(bot.blockAt(q.offset(1,0,0)),new Vec3(-1,0,0),{forceLook:true});await tick(5);const feet=q.offset(0,-2,0);if(!shell(feet)||!feet.equals(bot.entity.position.floored()))throw Error('SHELL_POST');global.P1Overland={feet,roof:q,at:Date.now()};global.P1DownPending=null;console.log('REFUGE_VERIFIED',feet,bot.health);return feet}
async function emerge(){const s=global.P1Overland;if(!s)return;if(!s.feet.equals(bot.entity.position.floored())||!shell(s.feet))throw Error('EMERGE_START');const coldCount=()=>bot.inventory.items().filter(i=>coldNames.includes(i.name)).reduce((a,i)=>a+i.count,0);if(coldCount()<2){let got=false;for(const d of dirs){const q=s.feet.plus(d).offset(0,1,0),b=bot.blockAt(q);if(!['dirt','grass_block'].includes(b.name))continue;const faces=[...dirs,new Vec3(0,1,0),new Vec3(0,-1,0)];if(!faces.every(v=>q.plus(v).equals(s.feet.offset(0,1,0))||full(bot.blockAt(q.plus(v)))))continue;await cut(b);for(let k=0;k<35&&coldCount()<2;k++)await tick(1);if(coldCount()>=2){got=true;console.log('EXIT_ONE_DIRT_ACTUAL',coldCount());break}}if(!got)throw Error('NEED_ONE_COLD_EXIT_RETAINED')}await cut(bot.blockAt(s.roof));for(let h=1;h<=2;h++){const b=bot.blockAt(s.roof.offset(0,h,0));if(b&&["spruce_log","spruce_leaves","oak_log","oak_leaves"].includes(b.name))await cut(b);else if(!air(b))throw Error('EMERGE_CEILING_'+b?.name);}for(let k=0;k<35&&coldCount()<3;k++)await tick(1);for(let y=s.feet.y;y<=s.roof.y;y++){await center(new Vec3(s.feet.x,y,s.feet.z));if(!stock())throw Error('UP_STOCK');await bot.equip(stock(),'hand');bot.setControlState('jump',true);for(let k=0;k<15&&bot.entity.position.y<y+.95;k++)await tick(1);try{await bot._placeBlockWithOptions(bot.blockAt(new Vec3(s.feet.x,y-1,s.feet.z)),new Vec3(0,1,0),{forceLook:true})}finally{bot.setControlState('jump',false)}await tick(10);if(!full(bot.blockAt(new Vec3(s.feet.x,y,s.feet.z)))||Math.abs(bot.entity.position.y-y-1)>.15)throw Error('UP_POST')}global.P1Overland=null;await arm();console.log('EMERGED_ACTUAL',bot.entity.position)}
async function cleanup(){if(global.P1DownPending&&!lost){try{await rescueCap()}catch(e){console.log('FINAL_CAP_FAILED',e.message)}}bot.pathfinder.setGoal(null);bot.clearControlStates();if(bot.entity.isInWater)bot.setControlState('jump',true);bot.deactivateItem();bot.removeListener('death',die);bot.removeListener('respawn',die);bot.removeListener('end',die);await arm();console.log('OVERLAND_END',JSON.stringify({p:bot.entity.position,hp:bot.health,food:bot.food,lost,protected:shell(bot.entity.position.floored()),water:bot.entity.isInWater,grounded:bot.entity.onGround,foes:foes().map(e=>[e.name,e.position.distanceTo(bot.entity.position)]),air:bot.oxygenLevel,selfAir:selfAir(),controls:controlsNow(),kit:bot.inventory.items().map(i=>[i.name,i.count,i.durabilityUsed]),offhand:bot.inventory.slots[45]?.name,refuge:global.P1Overland}));}
// Uses overland_lib definitions; runs rescue in the same program, before a tool boundary.
const stableNames=['dirt','cobblestone','sandstone','granite','diorite','andesite','spruce_planks'];
function cheapColumn(q){if(![-3,-2,-1,0].every(y=>full(bot.blockAt(q.offset(0,y,0)))))return false;if(!dirs.every(d=>[-2,-1].every(y=>full(bot.blockAt(q.plus(d).offset(0,y,0))))))return false;const hasPick=bot.inventory.items().some(i=>i.name.endsWith('_pickaxe'));return [0,-1,-2].every(y=>{const n=bot.blockAt(q.offset(0,y,0)).name;return ['grass_block','dirt'].includes(n)||(hasPick&&['stone','granite','diorite','andesite','sandstone'].includes(n))||(n==='sand'&&bot.inventory.items().some(i=>stableNames.includes(i.name)))});}
function contactThreat(){const eye=bot.entity.position.offset(0,1.62,0);return foes().find(e=>{if(Math.abs(e.position.y-bot.entity.position.y)>3&&!['skeleton','stray','witch'].includes(e.name))return false;const r=['skeleton','stray','witch'].includes(e.name)?16:e.name==='creeper'?13:10;if(e.position.distanceTo(bot.entity.position)>r)return false;const v=e.position.offset(0,1.2,0).minus(eye);return !bot.world.raycast(eye,v.unit(),v.norm())});}
async function centerDrop(q){await tick(5);await center(q);await tick(4);for(const a of ['x','z'])if(bot.entity.position[a]<q[a]+.33||bot.entity.position[a]>q[a]+.67)throw Error('DROP_CENTER_POST');}
async function immediateBurial(reason){life();bot.pathfinder.setGoal(null);bot.clearControlStates();for(let k=0;k<12&&!bot.entity.onGround;k++)await tick(1);const q=bot.entity.position.floored().offset(0,-1,0);if(bot.entity.isInWater||[0,1].some(y=>['water','bubble_column'].includes(bot.blockAt(bot.entity.position.floored().offset(0,y,0))?.name))||!bot.entity.onGround||!cheapColumn(q))return false;await centerDrop(q);if(!cheapColumn(q))return false;global.P1DownPending={feet:q.offset(0,-2,0),roof:q,at:Date.now()};let steps=0;try{for(let y=0;y>=-2;y--){life();const b=bot.blockAt(q.offset(0,y,0)),pick=bot.inventory.items().find(i=>i.name.endsWith('_pickaxe'));if(pick&&!['dirt','grass_block','sand'].includes(b.name))await bot.equip(pick,'hand');else await bot.unequip('hand');await bot.dig(b,true);steps++;for(let k=0;k<35&&(!bot.entity.onGround||Math.abs(bot.entity.position.y-q.y-y)>.12);k++)await tick(1);if(!bot.entity.onGround||Math.abs(bot.entity.position.y-q.y-y)>.12)throw Error('BURIAL_SETTLE')}for(let k=0;k<30&&!bot.inventory.items().some(i=>stableNames.includes(i.name));k++)await tick(1);const item=bot.inventory.items().find(i=>stableNames.includes(i.name));if(!item)throw Error('BURIAL_NO_CAP');await bot.equip(item,'hand');const rd=dirs.find(d=>full(bot.blockAt(q.plus(d))));if(!rd)throw Error('BURIAL_NO_ANCHOR');await bot._placeBlockWithOptions(bot.blockAt(q.plus(rd)),rd.scaled(-1),{forceLook:true});await tick(4);if(!shell(q.offset(0,-2,0)))throw Error('BURIAL_HULL');const inside=foes().filter(e=>Math.abs(e.position.x-q.x-.5)<.85&&Math.abs(e.position.z-q.z-.5)<.85&&e.position.y>=q.y-2.5&&e.position.y<q.y);if(inside.length)throw Error('BURIAL_OCCUPIED_'+inside.map(e=>e.name));global.P1Overland=global.P1DownPending;global.P1DownPending=null;console.log('IN_PROGRAM_BURIAL_VERIFIED',reason,bot.entity.position,bot.health);return true;}catch(e){console.log('BURIAL_ERROR',steps,e.message,JSON.stringify({q,p:bot.entity.position,ground:bot.entity.onGround,v:bot.entity.vel