function guardedMovement(sprint=false){const hazards=foes();const m=new Movements(bot);m.canDig=true;for(const b of bot.registry.blocksArray)if(!b.name.endsWith('_leaves')&&!['snow','short_grass','fern'].includes(b.name))m.blocksCantBreak.add(b.id);m.canOpenDoors=false;m.allowSprinting=false;m.allowParkour=true;m.allow1by1towers=false;m.scafoldingBlocks=[];m.maxDropDown=3;for(const n of['water','lava','fire','soul_fire','magma_block','sweet_berry_bush','powder_snow','cactus','nether_portal'])if(bot.registry.blocksByName[n])m.blocksToAvoid.add(bot.registry.blocksByName[n].id);m.exclusionAreasStep.push(b=>{const p=b.position||new Vec3(b.x,b.y,b.z);let c=0;for(const e of hazards){if(Math.abs(e.position.y-p.y)>3&&!['skeleton','stray','witch'].includes(e.name))continue;const d=e.position.distanceTo(p),r=e.name==='creeper'?11:['skeleton','stray','witch'].includes(e.name)?16:7;if(d<r)c+=(r-d)*20;}return c});bot.pathfinder.setMovements(m);bot.pathfinder.thinkTimeout=500;}
async function guardedWalk(ms=60000,forceAfterMs=null,target={x:148.5,z:2212.5},nightTrial=false){const hp0=bot.health;let hurt=false,buried=false,phase='WALK',flee=false,lastPlan=0,started=Date.now(),last=bot.entity.position.clone(),progress=Date.now();const onHealth=()=>{if(bot.health<hp0-.25)hurt=true};bot.on('health',onHealth);try{guardedMovement();while(Date.now()-started<ms){life();if(Math.hypot(target.x-bot.entity.position.x,target.z-bot.entity.position.z)<.7){phase='TARGET';break}const e=contactThreat(),late=!nightTrial&&bot.time.timeOfDay>=10000,forced=forceAfterMs!==null&&Date.now()-started>=forceAfterMs;const shouldBury=e||hurt||late||forced||Date.now()-started>ms-8000;if(shouldBury){const why=e?'PROXIMITY_'+e.name:hurt?'HURT':late?'BEFORE_NIGHT':forced?'CONTROLLED':'BUDGET';if(await immediateBurial(why)||await nativeRefuge()||await surfaceBox(why)){buried=true;phase='BURIED';break}flee=!!e||hurt;}
if(Date.now()-lastPlan>1000||!bot.pathfinder.goal){let tx=target.x,tz=target.z;guardedMovement(flee);if(flee){const es=foes();let dx=0,dz=0;for(const h of es){const d=Math.max(1,h.position.distanceTo(bot.entity.position));dx+=(bot.entity.position.x-h.position.x)/(d*d);dz+=(bot.entity.position.z-h.position.z)/(d*d)}const len=Math.hypot(dx,dz)||1;tx=bot.entity.position.x+dx/len*24;tz=bot.entity.position.z+dz/len*24;}else if(Date.now()-progress>3000){tx=bot.entity.position.x+15;tz=bot.entity.position.z+12;progress=Date.now()}bot.pathfinder.setGoal(new goals.GoalXZ(Math.floor(tx),Math.floor(tz)));lastPlan=Date.now()}
if(bot.entity.position.distanceTo(last)>.7){last=bot.entity.position.clone();progress=Date.now()}if(bot.entity.isInWater){bot.pathfinder.setGoal(null);bot.setControlState('jump',true);await bot.lookAt(bot.entity.position.offset(target.x-bot.entity.position.x,1.4,target.z-bot.entity.position.z),true);bot.setControlState('forward',true)}await tick(1);}if(!buried&&!lost){if(await immediateBurial('FINAL')||await nativeRefuge()||await surfaceBox('FINAL')){buried=true;phase='BURIED'}}return{phase,buried,hurt,hp0,hp:bot.health};}finally{bot.removeListener('health',onHealth);bot.pathfinder.setGoal(null);bot.clearControlStates();if(bot.entity.isInWater)bot.setControlState('jump',true);}}
async function alignAxis(axis,target,max=45){for(let k=0;k<max&&Math.abs(bot.entity.position[axis]-target)>.045;k++){await bot.lookAt(bot.entity.position.offset(axis==="x"?Math.sign(target-bot.entity.position.x)*5:0,1.4,axis==="z"?Math.sign(target-bot.entity.position.z)*5:0),true);bot.setControlState("sneak",true);bot.setControlState("forward",true);await tick(1);bot.clearControlStates();await tick(2)}if(Math.abs(bot.entity.position[axis]-target)>.09)throw Error("ALIGN_ACTUAL "+axis)}
async function transit(mode){bot.pathfinder.setGoal(null);bot.clearControlStates();const d=new Vec3(6,67,81);if(bot.entity.position.distanceTo(d)>5)throw Error("DOOR_START_FAR");if(mode==="exit"){await alignAxis("x",6.59375);await alignAxis("z",82.6)}else await alignAxis("x",6.59375);let b=bot.blockAt(d);if(b.name!=="spruce_door"||b.getProperties().facing!=="north")throw Error("DOOR_GEOMETRY");if(!b.getProperties().open){await bot.activateBlock(b);await tick(7)}await bot.lookAt(bot.entity.position.offset(0,1.4,mode==="exit"?-10:10),true);bot.setControlState("forward",true);try{for(let k=0;k<80;k++){await tick(1);if(mode==="exit"?bot.entity.position.z<79.5:bot.entity.position.z>82.3)break}}finally{bot.clearControlStates()}await tick(5);if(mode==="exit"?bot.entity.position.z>=79.6:bot.entity.position.z<=82.15||(bot.entity.position.y<67||bot.entity.position.y>67.65))throw Error("TRANSIT_ACTUAL");b=bot.blockAt(d);if(b.getProperties().open){await bot.activateBlock(b);await tick(10)}if(bot.blockAt(d).getProperties().open)throw Error("DOOR_NOT_CLOSED");console.log("TRANSIT_CLOSED_ACTUAL",mode,bot.entity.position);bot.chat("P1_"+mode+"_ACTUAL_CLOSED door6 KEEP_P1_WRITER_UNTIL_OPERATION_END "+bot.entity.position+" HP"+bot.health+" no pendingdoorcontrols; nextfieldphaseown.");}
async function surfaceBox(reason){life();bot.pathfinder.setGoal(null);bot.clearControlStates();if(!bot.entity.onGround||bot.entity.isInWater)return false;const p=bot.entity.position.floored(),floor=bot.blockAt(p.offset(0,-1,0));if(!full(floor)||['magma_block','lava'].includes(floor.name))return false;const order=[...dirs];const enemy=foes()[0];if(enemy){const dx=enemy.position.x-p.x,dz=enemy.position.z-p.z;order.sort((a,b)=>(b.x*dx+b.z*dz)-(a.x*dx+a.z*dz))}const missing=[];for(const d of order){for(const y of[-1,0,1]){const q=p.plus(d).offset(0,y,0),b=bot.blockAt(q);if(full(b))continue;if(!['air','cave_air','snow','short_grass','fern','tall_grass'].includes(b.name)&&!(y===-1&&b.name==='water'))return false;missing.push(q)}}const dirt=()=>bot.inventory.items().filter(i=>coldNames.includes(i.name)).reduce((a,i)=>a+i.count,0);if(dirt()<missing.length+2)return false;await centerDrop(p);async function put(q,ref,face){if(full(bot.blockAt(q)))return;const it=bot.inventory.items().find(i=>coldNames.includes(i.name));if(!it)throw Error('BOX_NO_CAP');await bot.equip(it,'hand');await bot._placeBlockWithOptions(bot.blockAt(ref),face,{forceLook:true});await tick(2);if(!full(bot.blockAt(q)))throw Error('BOX_BLOCK_ACK_'+q)}
for(const d of order){await put(p.plus(d).offset(0,-1,0),p.offset(0,-1,0),d);await put(p.plus(d),p.plus(d).offset(0,-1,0),new Vec3(0,1,0));await put(p.plus(d).offset(0,1,0),p.plus(d),new Vec3(0,1,0));}const roof=p.offset(0,2,0);if(!full(bot.blockAt(roof))){let d=order.find(d=>full(bot.blockAt(roof.plus(d))));if(!d){d=order[0];await put(roof.plus(d),p.plus(d).offset(0,1,0),new Vec3(0,1,0));}await put(roof,roof.plus(d),d.scaled(-1));}if(!shell(p))throw Error('BOX_HULL');const inside=foes().filter(e=>Math.abs(e.position.x-p.x-.5)<.85&&Math.abs(e.position.z-p.z-.5)<.85&&e.position.y>=p.y-.5&&e.position.y<p.y+2);if(inside.length)throw Error('BOX_OCCUPIED');global.P1SurfaceBox={feet:p,at:Date.now(),reason};global.P1Overland=null;console.log('SURFACE_BOX_VERIFIED',reason,p,bot.health,dirt());return true;}
async function exitSurfaceBox(target={x:148.5,z:2212.5},allowNight=false){const s=global.P1SurfaceBox;if(!s)return;if(!shell(s.feet)||!s.feet.equals(bot.entity.position.floored()))throw Error('BOX_EXIT_START');if(bot.time.timeOfDay>=10000&&!allowNight)throw Error('BOX_WAIT_DAY');const ds=[...dirs].sort((a,b)=>Math.hypot(target.x-s.feet.x-a.x,target.z-s.feet.z-a.z)-Math.hypot(target.x-s.feet.x-b.x,target.z-s.feet.z-b.z));let chosen=null;for(const d of ds){const door=s.feet.plus(d);if(foes().some(e=>Math.abs(e.position.y-door.y)<4&&e.position.distanceTo(door)<(e.name==='creeper'?8:['skeleton','stray','witch'].includes(e.name)?10:3)))continue;chosen=d;break}if(!chosen)throw Error('BOX_EXIT_THREAT');for(const y of[1,0]){const q=s.feet.plus(chosen).offset(0,y,0);if(!coldNames.includes(bot.blockAt(q).name))throw Error('BOX_EXIT_OWN_KIND');await cut(bot.blockAt(q));}global.P1SurfaceBox=null;console.log('BOX_EXIT_OPEN',s.feet.plus(chosen));}

async function nativeRefuge(){const p=bot.entity.position.floored(),cs=[];for(let x=-5;x<=5;x++)for(let z=-5;z<=5;z++)for(let y=-4;y<=2;y++){const q=p.offset(x,y-1,z);if(air(bot.blockAt(q.offset(0,1,0)))&&air(bot.blockAt(q.offset(0,2,0)))&&cheapColumn(q))cs.push(q);}cs.sort((a,b)=>a.distanceTo(bot.entity.position)-b.distanceTo(bot.entity.position));console.log('NATIVE_END_CANDIDATES',cs.slice(0,2));for(const q of cs.slice(0,2)){if(await moveTo(q.x+.5,q.z+.5,4000,.15,q.y+1)){if(await immediateBurial('NATIVE_LOCAL'))return true;}}return false;}

const selfAirKey=bot.registry.entitiesByName.player.metadataKeys?.indexOf('air_supply')??-1;
function selfAir(){const raw=selfAirKey>=0?bot.entity.metadata?.[selfAirKey]:null;return typeof raw==='number'?{raw,icons:Math.round(raw/15)}:null;}
function airIcons(){const a=selfAir();if(!a)throw Error('SELF_AIR_UNKNOWN');return a.icons;}
function controlsNow(){return Object.fromEntries(['forward','back','left','right','jump','sprint','sneak'].map(k=>[k,bot.getControlState(k)]));}
